let text = $input.item.json.output[0].content[0].text;

// Strip markdown backticks if present
text = text.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();

// Try normal parse first
try {
  const parsed = JSON.parse(text);
  return { json: parsed };
} catch (err) {
  // If parse fails, try to recover what we can
  // by finding the last "}" that closes a complete job object
  const jobsStart = text.indexOf('"jobs":[');
  if (jobsStart === -1) {
    throw new Error('No jobs array found in response');
  }

  let lastValidEnd = -1;
  let depth = 0;
  let inString = false;
  let escape = false;

  for (let i = jobsStart + 8; i < text.length; i++) {
    const c = text[i];
    if (escape) { escape = false; continue; }
    if (c === '\\') { escape = true; continue; }
    if (c === '"') { inString = !inString; continue; }
    if (inString) continue;
    if (c === '{') depth++;
    if (c === '}') {
      depth--;
      if (depth === 0) lastValidEnd = i;
    }
  }

  if (lastValidEnd === -1) {
    throw new Error('Could not recover any complete jobs');
  }

  // Rebuild a valid truncated JSON
  const truncated = text.substring(0, lastValidEnd + 1) + ']}';
  const parsed = JSON.parse(truncated);
  return { json: parsed };
}

